<?php
namespace App\Services;
use App\Models\Player;use App\Models\StatsbombPlayerMatch;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;
class StatsbombOpenDataService{
 private const BASE='https://raw.githubusercontent.com/statsbomb/open-data/master/data';private $localPlayers;
 public function import(int $competition=1267,int $season=107,int $limit=0):array{$matches=$this->get("matches/{$competition}/{$season}.json");if($limit>0)$matches=array_slice($matches,0,$limit);$this->localPlayers=Player::all();$rows=0;foreach($matches as$m){$id=(int)data_get($m,'match_id');$rows+=$this->store($m,$this->get("lineups/{$id}.json"),$this->get("events/{$id}.json"));}return['matches'=>count($matches),'player_matches'=>$rows,'competition'=>$competition,'season'=>$season];}
 private function get(string $path):array{$r=Http::timeout(90)->retry(2,500)->get(self::BASE.'/'.$path);if(!$r->successful())throw new \RuntimeException("StatsBomb Open Data request failed: {$path}");return$r->json()?:[];}
 private function store(array $match,array $lineups,array $events):int{$all=[];foreach($events as$e){$id=(int)data_get($e,'player.id');if(!$id)continue;$s=&$all[$id];$s??=$this->blank();$type=data_get($e,'type.name');if($type==='Shot'){$s['shots']++;$out=data_get($e,'shot.outcome.name');if(in_array($out,['Goal','Saved','Saved to Post'],true))$s['shots_on_target']++;if($out==='Goal')$s['goals']++;}if($type==='Pass'){$s['passes']++;if(!data_get($e,'pass.outcome.name'))$s['completed_passes']++;if(data_get($e,'pass.shot_assist')||data_get($e,'pass.goal_assist'))$s['key_passes']++;if(data_get($e,'pass.goal_assist'))$s['assists']++;}if($type==='Interception')$s['interceptions']++;if($type==='Duel'&&data_get($e,'duel.type.name')==='Tackle')$s['tackles']++;$card=data_get($e,'foul_committed.card.name');if(in_array($card,['Yellow Card','Second Yellow'],true))$s['yellow_cards']++;if(in_array($card,['Red Card','Second Yellow'],true))$s['red_cards']++;}
  $count=0;$home=data_get($match,'home_team.home_team_name');$away=data_get($match,'away_team.away_team_name');foreach($lineups as$side){$team=(string)data_get($side,'team_name');$opponent=$team===$home?$away:$home;foreach(data_get($side,'lineup',[])as$p){$id=(int)data_get($p,'player_id');$name=(string)data_get($p,'player_name');$positions=data_get($p,'positions',[]);$local=$this->local($name,(string)data_get($p,'player_nickname'));StatsbombPlayerMatch::updateOrCreate(['statsbomb_match_id'=>(int)data_get($match,'match_id'),'statsbomb_player_id'=>$id],['player_id'=>$local?->id,'player_name'=>$name,'nickname'=>data_get($p,'player_nickname'),'country'=>data_get($p,'country.name'),'team'=>$team,'opponent'=>$opponent,'match_date'=>data_get($match,'match_date'),'competition'=>data_get($match,'competition.competition_name'),'season'=>data_get($match,'season.season_name'),'started'=>collect($positions)->contains(fn($x)=>(int)data_get($x,'from_period')===1&&data_get($x,'from')==='00:00'),'minutes'=>$this->minutes($positions),...($all[$id]??$this->blank()),'raw_stats'=>['positions'=>$positions,'source'=>'StatsBomb Open Data']]);$count++;}}return$count;}
 private function local(string $name,string $nickname):?Player{$names=array_filter([$this->normal($name),$this->normal($nickname)]);return$this->localPlayers->first(fn($p)=>in_array($this->normal($p->name),$names,true));}
 private function minutes(array $positions):?int{if(!$positions)return null;$seconds=0;foreach($positions as$p){$from=$this->seconds((string)data_get($p,'from','00:00'));$to=$this->seconds((string)data_get($p,'to','00:00'));if($to>$from)$seconds+=$to-$from;}return(int)round($seconds/60);}
 private function seconds(string $time):int{$p=array_map('intval',explode(':',$time));return count($p)===3?$p[0]*3600+$p[1]*60+$p[2]:($p[0]??0)*60+($p[1]??0);}
 private function normal(string $v):string{return trim(preg_replace('/[^a-z0-9]+/',' ',Str::lower(Str::ascii($v))));}private function blank():array{return array_fill_keys(['goals','assists','shots','shots_on_target','passes','completed_passes','key_passes','tackles','interceptions','yellow_cards','red_cards'],0);}
}
